hanged+=(s,e)=>SchedulePotentialStructureSettings();potentials.CurrentCellChanged+=(s,e)=>SchedulePotentialStructureSettings();potentials.CurrentCellDirtyStateChanged+=(s,e)=>{if(potentials.IsCurrentCellDirty)potentials.CommitEdit(DataGridViewDataErrorContexts.Commit);};potentials.EditingControlShowing+=(s,e)=>e.Control.Font=Theme.Input();potentials.UserDeletedRow+=(s,e)=>GridChanged();var pixelGrid=new PixelGridHost(potentials);page.Controls.Add(pixelGrid);pixelGrid.BringToFront();}
