 class SearchToggleForm:Form {
  readonly string[] all;readonly HashSet<string> selected;readonly int maximum;PixelTextBox search;PixelCheckedListBox list;public string[] Selected{get{return all.Where(selected.Contains).ToArray();}}
  public SearchToggleForm(string title,IEnumerable<string> values,IEnumerable<string> current,int max){Load+=(s,e)=>Theme.Enlarge(this);Text=title;Size=new Size(520,650);StartPosition=FormStartPosition.CenterParent;BackColor=Color.White;Font=Theme.UI();maximum=max;all=values.Concat(current??new string[0]).Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct().ToArray();selected=new HashSet<string>((current??new string[0]).Select(x=>x.Trim()).Where(x=>x.Length>0));search=new PixelTextBox{Dock=DockStyle.Top,Font=Theme.Input()};list=new PixelCheckedListBox{Dock=DockStyle.Fill,CheckOnClick=true,Font=Theme.Input(),IntegralHeight=false};search.TextChanged+=(s,e)=>RefreshList();list.ItemCheck+=(s,e)=>{if(refreshing)return;string value=list.Items[e.Index].ToString();if(e.NewValue==CheckState.Checked){if(maximum>1&&selected.Count>=maximum&&!selected.Contains(value)){e.NewValue=CheckState.Unchecked;return;}if(maximum==1){selected.Clear();BeginInvoke((Action)RefreshList);}selected.Add(value);}else selected.Remove(value);};var ok=new FlatButton{Text="선택 적용",Dock=DockStyle.Bottom,Height=50,Primary=true};ok.Click+=(s,e)=>{if(maximum==1&&selected.Count>1){GameDialog.Show(this,"하나만 선택하세요.");return;}DialogResult=DialogResult.OK;};Controls.Add(list);Controls.Add(search);Controls.Add(new PixelLabel{Text="검색",Dock=DockStyle.Top,Height=30});Controls.Add(ok);RefreshList();}
  bool refreshing;
  void RefreshList(){refreshing=true;string q=search.Text.Trim();list.Items.Clear();foreach(string value in all.Where(x=>q.Length==0||x.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0)){int index=list.Items.Add(value);list.SetItemChecked(index,selected.Contains(value));}refreshing=false;}
 }

 static class DataEditorProgram {
  static DataEditorProgram(){Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);}
  static void Capture(Form form,string path){using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));bitmap.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
  [STAThread]public static int Main(string[] args){try{Theme.Instant=args.Length>0;if(args.Length>1&&args[0]=="--export-components"){PotentialParts.Export(args[1]);return 0;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Fonts.Load();var form=new DataEditorForm();if(args.Length>1&&args[0]=="--render-preview"){form.Shown+=(s,e)=>{form.Sample();form.TestCatalogUi();form.SelectTabForTest(2);Capture(form,args[1]);form.SelectTabForTest(1);Capture(form,args[1]+".pokemon.png");form.SelectTabForTest(3);Capture(form,args[1]+".sheet.png");form.SelectTabForTest(4);Capture(form,args[1]+".moves.png");form.SelectTabForTest(5);Capture(form,args[1]+".potentials.png");form.SelectTabForTest(6);Capture(form,args[1]+".abilities.png");form.CloseForTest();};}Application.Run(form);return 0;}catch(Exception ex){if(args.Length>0){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"data-editor-error.txt"),ex.ToString());return 1;}GameDialog.Show(ex.Message,"데이터 편집기 오류");return 1;}}
 }
